<?php
require_once __DIR__.'/includes/bootstrap.php';
require_once __DIR__.'/includes/student_lib.php';
require_once __DIR__.'/includes/learn_lib.php';
require_once __DIR__.'/includes/payments_lib.php';
require_once __DIR__.'/includes/exams_lib.php';
stu_guard('sdash'); refresh_batches(); $pageKey='sdash'; require __DIR__.'/includes/header.php';
$sid=stu_id(); $st=stu_row(); $bs=stu_batches(); $ids=stu_ids(); $today=date('Y-m-d'); $wd=date('D'); $nowT=date('H:i:s');
function rows(string $sql,array $p=[]): array { $q=db()->prepare($sql); $q->execute($p); return $q->fetchAll(); }
$todayCls=[]; $subs=array_column(rows("SELECT sb.batch_id,su.full_name n FROM substitutions sb JOIN users su ON su.id=sb.substitute_id WHERE sb.class_date=CURDATE() AND sb.batch_id IN ($ids)"),'n','batch_id');
foreach($bs as $b){ if($b['status']!=='active'||$b['start_date']>$today||$b['end_date']<$today) continue; if($b['class_days']!==''&&$b['class_days']!==null&&!in_array($wd,explode(',',$b['class_days']),true)) continue; $todayCls[]=$b; }
usort($todayCls,fn($a,$b)=>strcmp($a['start_time'],$b['start_time']));
$live=array_values(array_filter(rows("SELECT m.id,m.title,m.url,m.passcode,m.starts_at,m.duration_min,b.name bname,c.name cname FROM materials m JOIN batches b ON b.id=m.batch_id JOIN courses c ON c.id=b.course_id WHERE m.batch_id IN ($ids) AND m.kind='live' AND m.publish=1 AND m.starts_at>=NOW()-INTERVAL 1 DAY ORDER BY m.starts_at LIMIT 10"),fn($m)=>live_state($m['starts_at'],$m['duration_min'])[1]!=='dark'));
$live=array_slice($live,0,3);
$pendBase="FROM materials m JOIN batches b ON b.id=m.batch_id JOIN courses c ON c.id=b.course_id LEFT JOIN assignment_submissions sb ON sb.material_id=m.id AND sb.student_id=? LEFT JOIN homework_records h ON h.material_id=m.id AND h.student_id=? WHERE m.batch_id IN ($ids) AND m.kind='homework' AND m.publish=1 AND sb.id IS NULL AND (h.id IS NULL OR h.status='missing') AND b.status='active'";
$pendN=(int)rows("SELECT COUNT(*) c $pendBase",[$sid,$sid])[0]['c'];
$pend=rows("SELECT m.id,m.title,m.due_date,c.name cname $pendBase ORDER BY (m.due_date IS NULL),m.due_date LIMIT 4",[$sid,$sid]);
$notes=rows("SELECT m.id,m.title,m.description,m.created_at,b.id bid,b.name bname FROM materials m JOIN batches b ON b.id=m.batch_id WHERE m.batch_id IN ($ids) AND m.kind='notice' AND m.publish=1 ORDER BY m.id DESC LIMIT 4");
$exams=rows("SELECT x.title,x.exam_date,x.start_time,b.name bname,c.name cname FROM exams x JOIN batches b ON b.id=x.batch_id JOIN courses c ON c.id=b.course_id WHERE x.batch_id IN ($ids) AND x.exam_date BETWEEN CURDATE() AND DATE_ADD(CURDATE(),INTERVAL 14 DAY) ORDER BY x.exam_date,x.start_time LIMIT 4");
$res=rows("SELECT x.title,x.exam_type,x.max_marks,m.marks,m.absent,t.code tcode FROM exam_marks m JOIN exams x ON x.id=m.exam_id JOIN batches b ON b.id=x.batch_id JOIN courses c ON c.id=b.course_id JOIN course_types t ON t.id=c.type_id WHERE m.student_id=? AND m.marks IS NOT NULL ORDER BY x.exam_date DESC LIMIT 3",[$sid]);
$att=array_column(rows("SELECT status,COUNT(*) c FROM attendance WHERE student_id=? GROUP BY status",[$sid]),'c','status'); $pa=(int)($att['present']??0); $aa=(int)($att['absent']??0); $apct=($pa+$aa)?round($pa/($pa+$aa)*100):null;
$fee=rows("SELECT COALESCE(SUM(i.amount-i.paid),0) bal,COALESCE(SUM(IF(i.due_date<CURDATE(),i.amount-i.paid,0)),0) od,MIN(IF(i.amount-i.paid>0.004,i.due_date,NULL)) nxt FROM installments i JOIN fee_accounts a ON a.id=i.account_id WHERE a.student_id=?",[$sid])[0];
$active=count(array_filter($bs,fn($b)=>$b['status']==='active')); $hr=(int)date('G'); $greet=$hr<12?'Good morning':($hr<17?'Good afternoon':'Good evening');
function card(string $l,string $v,string $icon,string $href,string $c='var(--blue)'): void { echo '<a class="card-ui quick" href="'.e($href).'"><span class="ic" style="color:'.$c.'"><i class="bi '.$icon.'"></i></span><span><span class="stat" style="font-size:1.35rem;display:block">'.e($v).'</span><span class="lbl">'.e($l).'</span></span></a>'; }
?>
<?php if(isset($_GET['pw'])):?><div class="alert alert-success rounded-4">Your password was updated.</div><?php endif;?>
<div class="mb-3"><div class="lbl"><?=e(date('l, j F Y'))?></div><div class="stat" style="font-size:1.5rem"><?=$greet?>, <?=e($st['first_name']??'')?> 👋</div><div class="lbl"><?=e($st['student_code']??'')?> · <?=e($st['brname']??'')?></div></div>
<?php if(($st['status']??'')==='inactive'):?><div class="alert alert-warning rounded-4"><b>Your student status is inactive</b> because of recent absences. It becomes active again when you are marked present. Please attend your next class<?=!empty($st['brphone'])?' or call '.e($st['brphone']):''?>.</div><?php endif;?>
<?php if(!$bs):?><div class="card-ui text-center lbl">You are not enrolled in any class yet. Please contact your institute.</div><?php else:?>
<div class="kpi-grid mb-3"><?php card('Active classes',(string)$active,'bi-journal-bookmark-fill','my_classes.php'); card('Attendance',$apct===null?'—':$apct.'%','bi-check2-square','my_attendance.php',$apct===null?'var(--blue)':pct_color($apct));
 card('Assignments to do',(string)$pendN,'bi-journal-check','my_assignments.php',$pendN?'#e08a00':'#1e9e5a'); card('Fee balance',(float)$fee['bal']>0.004?money($fee['bal']):'Paid up','bi-wallet2','my_fees.php',(float)$fee['od']>0.004?'#d9534f':'#1e9e5a');?></div>
<?php if((float)$fee['od']>0.004):?><a href="my_fees.php" class="alert alert-danger rounded-4 d-block text-decoration-none"><i class="bi bi-exclamation-triangle-fill"></i> You have overdue fees of <b><?=money($fee['od'])?></b>. Tap to see details.</a><?php elseif((float)$fee['bal']>0.004&&$fee['nxt']):?><a href="my_fees.php" class="alert alert-info rounded-4 d-block text-decoration-none"><i class="bi bi-wallet2"></i> Next payment due <b><?=e(date('j M Y',strtotime($fee['nxt'])))?></b>.</a><?php endif;?>
<div class="row g-3">
<?php if($live):?><div class="col-12"><div class="card-ui"><div class="fw-bold mb-2"><i class="bi bi-camera-video-fill"></i> Live classes</div>
<?php foreach($live as $m): $ls=live_state($m['starts_at'],$m['duration_min']);?><div class="border-top py-2 d-flex flex-wrap justify-content-between gap-2"><div><b><?=e($m['title'])?></b> <span class="badge rounded-pill text-bg-<?=$ls[1]?>"><?=e($ls[0])?></span><div class="lbl"><?=e(date('D j M, g:i A',strtotime($m['starts_at'])))?> · <?=e($m['cname'])?> · <?=e($m['bname'])?><?=$m['passcode']?' · Passcode '.e($m['passcode']):''?></div></div>
<?php if($ls[2]):?><a class="btn-ui text-decoration-none" href="<?=e($m['url'])?>" target="_blank" rel="noopener noreferrer">Join class</a><?php else:?><span class="lbl align-self-center">Join opens 10 min before</span><?php endif;?></div><?php endforeach;?></div></div><?php endif;?>
<div class="col-lg-6"><div class="card-ui h-100"><div class="fw-bold mb-2">Today's classes</div>
<?php foreach($todayCls as $c): $sg=$nowT>=$c['start_time']&&$nowT<=$c['end_time']?['Now','primary']:($nowT<$c['start_time']?['Upcoming','secondary']:['Done','success']);?><a href="my_class.php?id=<?=$c['id']?>" class="d-block text-decoration-none text-reset border-top py-2"><div class="d-flex justify-content-between"><b style="color:var(--blue)"><?=e(substr($c['start_time'],0,5))?>–<?=e(substr($c['end_time'],0,5))?></b><span class="badge rounded-pill text-bg-<?=$sg[1]?>"><?=$sg[0]?></span></div><div><?=e($c['cname'])?> · <?=e($c['name'])?></div><div class="lbl"><?=e($subs[$c['id']]??$c['tch']??'Teacher to be announced')?><?=isset($subs[$c['id']])?' (substitute)':''?></div></a><?php endforeach; if(!$todayCls):?><div class="lbl">No classes today. Enjoy your day!</div><?php endif;?></div></div>
<div class="col-lg-6"><div class="card-ui h-100"><div class="fw-bold mb-2">To do</div>
<?php foreach($pend as $a): $over=$a['due_date']&&$a['due_date']<$today;?><a href="my_assignment.php?id=<?=$a['id']?>" class="d-block text-decoration-none text-reset border-top py-2"><div class="d-flex justify-content-between gap-2"><span><?=e($a['title'])?></span><span class="lbl <?=$over?'text-danger':''?>"><?=$a['due_date']?($over?'Overdue ':'Due ').e(date('j M',strtotime($a['due_date']))):'No due date'?></span></div><div class="lbl"><?=e($a['cname'])?></div></a><?php endforeach; if(!$pend):?><div class="lbl">You are all caught up. 🎉</div><?php endif;?></div></div>
<?php if($notes):?><div class="col-lg-6"><div class="card-ui h-100"><div class="fw-bold mb-2"><i class="bi bi-megaphone-fill"></i> Announcements</div>
<?php foreach($notes as $n):?><a href="my_class.php?id=<?=$n['bid']?>&type=notice" class="d-block text-decoration-none text-reset border-top py-2"><b><?=e($n['title'])?></b><div class="lbl"><?=e(mb_strimwidth($n['description']??'',0,120,'…'))?></div><div class="lbl"><?=e($n['bname'])?> · <?=e(substr($n['created_at'],0,10))?></div></a><?php endforeach;?></div></div><?php endif;?>
<?php if($exams):?><div class="col-lg-6"><div class="card-ui h-100"><div class="fw-bold mb-2">Upcoming exams</div>
<?php foreach($exams as $x):?><div class="border-top py-2"><div class="d-flex justify-content-between"><span><?=e($x['title'])?></span><span class="lbl"><?=e(date('D j M',strtotime($x['exam_date'])))?><?=$x['start_time']?' · '.e(substr($x['start_time'],0,5)):''?></span></div><div class="lbl"><?=e($x['cname'])?> · <?=e($x['bname'])?></div></div><?php endforeach;?></div></div><?php endif;?>
<?php if($res):?><div class="col-lg-6"><div class="card-ui h-100"><div class="d-flex justify-content-between mb-2"><b>Latest results</b><a href="my_results.php" class="lbl">See all</a></div>
<?php foreach($res as $r): $pc=$r['max_marks']>0?$r['marks']/$r['max_marks']*100:0;?><div class="border-top py-2 d-flex justify-content-between"><span><?=e($r['title'])?><div class="lbl"><?=e(exam_outcome($r['exam_type'],$r['tcode'],$pc))?></div></span><span><b><?=e(rtrim(rtrim(number_format((float)$r['marks'],2,'.',''),'0'),'.'))?></b> / <?=e(rtrim(rtrim(number_format((float)$r['max_marks'],2,'.',''),'0'),'.'))?> <span class="badge rounded-pill" style="background:<?=pct_color($pc)?>"><?=grade_for($pc)?></span></span></div><?php endforeach;?></div></div><?php endif;?>
</div><?php endif;?>
<?php require __DIR__.'/includes/footer.php';
